import{_ as a,c as t,o as _,ah as n}from"./chunks/framework.BxT5r71R.js";const h=JSON.parse('{"title":"已进入确立公司运营机制的阶段","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART2/17_已进入确立公司运营机制的阶段.md","filePath":"zh-cn/Management2/PART2/17_已进入确立公司运营机制的阶段.md"}'),o={name:"zh-cn/Management2/PART2/17_已进入确立公司运营机制的阶段.md"};function r(p,e,s,i,S,c){return _(),t("div",null,[...e[0]||(e[0]=[n('<p>► 2023年8月</p><h2 id="已进入确立公司运营机制的阶段" tabindex="-1">已进入确立公司运营机制的阶段 <a class="header-anchor" href="#已进入确立公司运营机制的阶段" aria-label="Permalink to &quot;已进入确立公司运营机制的阶段&quot;">​</a></h2><p>#管理 #良好的氛围 #积极的烦恼 #可复制性 #个人属性与法人属性 #BE:FIRST</p><h3 id="过去-bmsg主要依靠个人属性上的优势运转。接下来-必须在组织规则和组织运营上建立机制-确保公司稳健运转。" tabindex="-1">“过去，BMSG主要依靠个人属性上的优势运转。接下来，必须在组织规则和组织运营上建立机制，确保公司稳健运转。” <a class="header-anchor" href="#过去-bmsg主要依靠个人属性上的优势运转。接下来-必须在组织规则和组织运营上建立机制-确保公司稳健运转。" aria-label="Permalink to &quot;“过去，BMSG主要依靠个人属性上的优势运转。接下来，必须在组织规则和组织运营上建立机制，确保公司稳健运转。”&quot;">​</a></h3><p><strong>2023年，BMSG的发展势头十分强劲。BE:FIRST持续活跃，MAZZEL正式出道，Novel Core宣布将于2024年举办日本武道馆演出，Aile The Shota也举办了首次个人专场演出。edhiii boi则计划于11月举办个人专场演出。9月1日，REIKO将预出道，届时，进入THE FIRST最终评审的10人都将实现出道。不仅如此，在7月举办的BMSG TRAINEE Showcase2023上，RUI、TAIKI、KANON也展现出显著的成长，BMSG的新生代更加值得期待。SKY-HI如何看待眼下的状态？</strong></p><p>现在真是个很棒的时期，所有艺人看起来都很开心。不管去哪个工作现场，氛围都很好，身为社长的我也能自信地说出这一点。这种状态再好不过了。我觉得，人有烦恼很正常，真正难受的，或许不是有烦恼，而是烦恼无从解决。负面情绪往往很难彻底摆脱，艺人如果陷在其中，确实会很辛苦。不过，现在BMSG的艺人即使有烦恼、有纠结，也都是积极的烦恼。我觉得，我们现在已经把负面情绪降到了最低。某种意义上，大家在精神上处于无可匹敌的状态。氛围这么好的时候，往往还会出现一些意想不到的惊喜。</p><p><strong>从经营者的角度来看，他又如何理解这一状态？</strong></p><p>我觉得，现在到了一个关键阶段：公司能不能真正作为一个组织运转起来？眼下的良好氛围和亮眼业绩，能否依靠机制持续实现，也就是能否具备可复制性，这一点很重要。我想，我们正处在这样的节点上。</p><p>一路走来，BMSG在一定程度上是靠个人特质推动发展的。也就是说，支撑公司运转的，是个人属性上的优势。接下来，我认为必须在组织规则和组织运营上建立机制，确保公司稳健运转。</p><p>比如，即使我在亚洲其他国家待上2个月左右，公司也必须保持良好的状态。这不正是BMSG作为一家公司，现在必须实现的成长吗？至少明年（2024年），我想一定会有需要我亲自前往亚洲其他国家的时候。虽然目前还没有确定的安排，但作为社长，我希望亲自过去，扩大BMSG在亚洲的影响力。真到了那个时候，还是会有点担心啊……不过，如今不管身在何处都能保持联系，应该也没问题吧。</p><p><strong>这是否意味着，BMSG即将全面进军海外？</strong></p><p>面对现实，不走向全球，就没有未来。</p><p>我是这么想的。为此，无论是我、BE:FIRST、MAZZEL，还是旗下的个人艺人，想必也都需要像在日本全国巡演一样，亲自前往当地。不过，我还是希望以东京为根基，在这里创造文化，再向外传播。</p>',13)])])}const d=a(o,[["render",r]]);export{h as __pageData,d as default};
